def minCost(grid, k):
    # Process teleport layers t = 0..k. Within a layer, only right/down moves (paying
    # the destination value) are allowed, starting from that layer's entry costs. A
    # teleport (free) jumps from a cell to any cell with value <= the source value,
    # advancing to the next layer. Entry cost of a target is the min over all cells
    # whose value is >= the target's value.
    m, n = len(grid), len(grid[0])
    INF = float('inf')
    maxv = max(max(row) for row in grid)

    start = [[INF] * n for _ in range(m)]
    start[0][0] = 0
    ans = INF
    for t in range(k + 1):
        best = [[INF] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                v = start[i][j]
                if i > 0 and best[i - 1][j] + grid[i][j] < v:
                    v = best[i - 1][j] + grid[i][j]
                if j > 0 and best[i][j - 1] + grid[i][j] < v:
                    v = best[i][j - 1] + grid[i][j]
                best[i][j] = v
        if best[m - 1][n - 1] < ans:
            ans = best[m - 1][n - 1]
        if t < k:
            min_for_val = [INF] * (maxv + 2)
            for i in range(m):
                for j in range(n):
                    g = grid[i][j]
                    if best[i][j] < min_for_val[g]:
                        min_for_val[g] = best[i][j]
            # suffix min: cheapest cell with value >= v
            suf = [INF] * (maxv + 2)
            run = INF
            for v in range(maxv, -1, -1):
                if min_for_val[v] < run:
                    run = min_for_val[v]
                suf[v] = run
            nxt = [[suf[grid[i][j]] for j in range(n)] for i in range(m)]
            start = nxt
    return ans
